namespace Reflectable { public sealed class SkillManager { readonly PlayerStats stats; readonly ExperienceManager xp; public SkillManager(PlayerStats p,ExperienceManager e){stats=p;xp=e;} public bool Upgrade(string skill){int cost=skill=="EXTRA BALL"?2:1;if(!xp.Spend(cost))return false;switch(skill){case "POWER":stats.Power++;break;case "RICOCHET":stats.Ricochet++;break;case "EXTRA BALL":stats.ExtraBall++;break;case "MAX HP":stats.MaxHpLevel++;stats.HealMax();break;}return true;} } }
